// Refresh only an idle screen; never interrupt speech, drafts or captions.
let checkingRelease=false;
async function checkForAppUpdate(){if(checkingRelease||document.visibilityState!=='visible'||mic||$('#text-input').value.trim()||records.size||participants.some(p=>p.id!==selfId)||(room&&!room.local))return;checkingRelease=true;try{const url=new URL('index.html',location.href);url.searchParams.set('release-check',String(Date.now()));url.hash='';const response=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!response.ok)return;const doc=new DOMParser().parseFromString(await response.text(),'text/html'),incoming=doc.querySelector('script[type="module"][src*="app.js"]')?.getAttribute('src'),current=document.querySelector('script[type="module"][src*="app.js"]')?.getAttribute('src');const styleRelease=d=>Array.from(d.querySelectorAll('link[rel="stylesheet"][href^="web/"]')).map(e=>e.getAttribute('href')).join('|');if(!incoming||(incoming===current&&styleRelease(doc)===styleRelease(document))||mic||$('#text-input').value.trim()||records.size||participants.some(p=>p.id!==selfId)||(room&&!room.local))return;sessionStorage.setItem('tsuyaku-update-tab',tab);const fresh=new URL('index.html',location.href);fresh.searchParams.set('update',new URL(incoming,location.href).searchParams.get('v')||String(Date.now()));fresh.hash='';location.replace(fresh);}catch{}finally{checkingRelease=false;}}
setInterval(()=>void checkForAppUpdate(),60000);
window.addEventListener('pageshow',event=>{pageClosing=false;void resumeCallReception();if(event.persisted&&room?.mode==='lesson'&&socket?.readyState!==1&&!intentionalClose)void connect().then(()=>startConnectionTimers()).catch(e=>showConnectionError(e));void checkForAppUpdate();});
function suspendBackgroundInterpretation(){for(const controller of roomPreparations.values())controller.abort();roomPreparations.clear();for(const entry of preparedConversations.values())disposePreparation(entry.prepared);preparedConversations.clear();if(!room)++sessionEpoch;pauseConversation('background');}
function pauseConversation(reason='background'){
 if(reason==='background'&&!['face','interpreter','lesson'].includes(room?.mode))return;if(!room||room.joinBlocked)return;
 const wasActive=mic||microphoneStarting||localJobs.size>0||!!localRequest||room.mode==='interpreter'&&!backgroundCallPaused;
 ++microphoneActivation;mic=false;idleWatch.stop();stopRecognition();
 localStream?.getTracks().forEach(track=>track.stop());localStream=null;
 cancelLocalTranslations(true);if(room.local||room.mode==='face')pending.clear();localTimings.clear();
 ledger.microphone(false);
 if(room.mode==='interpreter'){
  backgroundCallPaused=true;intentionalClose=true;++sessionEpoch;
  clearTimeout(reconnectTimer);clearTimeout(authTimer);clearInterval(heartbeat);clearInterval(refreshTimer);
  socket?.close();socket=null;connectedAt=null;recoveryStartedAt=null;reconnectAttempts=0;
  participants=[];$('#participants').replaceChildren();updateLiveActions();renderCallInvite();status('チャットを一時停止しました');
 }
 const button=$('#microphone');paintButton(button,'マイクをONにする','microphone');button.setAttribute('aria-pressed','false');
 if(wasActive){ledger.event(reason==='idle'?'idle_pause':'background_pause');recordPause(reason,undefined,{mode:room.mode,scope:room.mode==='interpreter'?'conversation':'microphone'});message(reason==='idle'?'発話がないためマイクを停止しました。再開するときはマイクをONにしてください。':room.mode==='interpreter'?'画面を離れたためチャットを一時停止しました。マイクをONにすると同じルームへ再接続します。':'画面を離れたためマイクを停止しました。再開するときはマイクをONにしてください。');}
}
let receptionResuming=false;
async function resumeCallReception(){
 if(receptionResuming||!room||room.joinBlocked||room.mode!=='interpreter'||!backgroundCallPaused||pageClosing||document.visibilityState!=='visible')return;
 receptionResuming=true;const activeRoom=room,epoch=sessionEpoch;backgroundCallPaused=false;intentionalClose=false;
 try{await connect();if(room!==activeRoom||epoch!==sessionEpoch||backgroundCallPaused||pageClosing)return;startConnectionTimers();ledger.event('caption_reception_resumed');message('字幕の受信へ再接続しています。話すときはマイクをONにしてください。');}
 catch(e){if(room===activeRoom&&epoch===sessionEpoch){backgroundCallPaused=true;intentionalClose=true;showConnectionError(e);}}
 finally{receptionResuming=false;}
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){void checkForAppUpdate();void resumeCallReception();if(!room&&['face','interpreter'].includes(tab))void activateTab(tab);}else suspendBackgroundInterpretation();});
window.addEventListener('pagehide',suspendBackgroundInterpretation);

// Presentation observes state changes without polling or starting network work.
