function fitVisibleViewport(){const v=window.visualViewport;if(!v||v.scale!==1){document.documentElement.style.removeProperty('--visible-app-height');document.documentElement.style.removeProperty('--keyboard-inset');document.documentElement.dataset.keyboardOpen='false';return;}const height=Math.min(innerHeight,v.height+(v.offsetTop||0)),inset=Math.max(0,innerHeight-height);document.documentElement.style.setProperty('--visible-app-height',height+'px');document.documentElement.style.setProperty('--keyboard-inset',inset+'px');document.documentElement.dataset.keyboardOpen=String(inset>100);}window.visualViewport?.addEventListener('resize',fitVisibleViewport);window.visualViewport?.addEventListener('scroll',fitVisibleViewport);window.addEventListener('resize',fitVisibleViewport);fitVisibleViewport();
